package web

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	ReadHeaderTimeout = 5 * time.Second
	ReadTimeout       = 15 * time.Second
	WriteTimeout      = 30 * time.Second
	IdleTimeout       = 60 * time.Second
	ShutdownTimeout   = 10 * time.Second
	MaxInFlight       = 32
)

type Options struct {
	Listen        string
	OpenBrowser   bool
	Queries       app.WebQueries
	Operations    app.WebOperations
	Runs          app.RunUseCases
	Stdout        io.Writer
	Diagnostics   io.Writer
	ListenFunc    func(string, string) (net.Listener, error)
	LaunchBrowser func(context.Context, string) error
	Now           func() time.Time
	RequestID     func() string
}

func Run(ctx context.Context, opts Options) error {
	if ctx == nil {
		ctx = context.Background()
	}
	if err := app.ValidateLoopbackListen(opts.Listen); err != nil {
		return fmt.Errorf("validate listen address: %w", err)
	}
	if err := ValidateServerPolicy(DefaultServerPolicy()); err != nil {
		return fmt.Errorf("validate local-web policy: %w", err)
	}
	if opts.Queries == nil {
		return errors.New("web queries are required")
	}
	if opts.Stdout == nil {
		opts.Stdout = io.Discard
	}
	if opts.Diagnostics == nil {
		opts.Diagnostics = io.Discard
	}
	diagnostics := &lockedWriter{writer: opts.Diagnostics}
	if opts.ListenFunc == nil {
		opts.ListenFunc = net.Listen
	}

	listener, err := opts.ListenFunc("tcp", opts.Listen)
	if err != nil {
		return fmt.Errorf("listen on configured loopback address: %w", err)
	}
	defer listener.Close()
	authority, err := canonicalAuthority(listener.Addr())
	if err != nil {
		return err
	}
	if err := app.ValidateLoopbackListen(authority); err != nil {
		return fmt.Errorf("listener resolved outside loopback policy: %w", err)
	}
	origin := "http://" + authority
	if reconciler, ok := opts.Operations.(app.OperationReconciler); ok {
		if err := reconciler.ReconcileOperations(ctx); err != nil {
			_ = listener.Close()
			return fmt.Errorf("reconcile interrupted operations: %w", err)
		}
	}

	operationRoot, cancelOperations := context.WithCancel(context.Background())
	defer cancelOperations()
	hub := newOperationHub(operationRoot, opts.Operations, opts.Now, opts.RequestID)
	handler, err := NewHandler(HandlerOptions{
		Queries:     opts.Queries,
		Operations:  opts.Operations,
		Runs:        opts.Runs,
		Authority:   authority,
		Diagnostics: diagnostics,
		Now:         opts.Now,
		RequestID:   opts.RequestID,
		RootContext: operationRoot,
		Hub:         hub,
	})
	if err != nil {
		return fmt.Errorf("initialize web presentation: %w", err)
	}
	server := &http.Server{
		Handler:           handler,
		ReadHeaderTimeout: ReadHeaderTimeout,
		ReadTimeout:       ReadTimeout,
		WriteTimeout:      WriteTimeout,
		IdleTimeout:       IdleTimeout,
		BaseContext:       func(net.Listener) context.Context { return ctx },
	}

	if _, err := fmt.Fprintf(opts.Stdout, "Dashboard: %s/\n", origin); err != nil {
		return fmt.Errorf("write dashboard URL: %w", err)
	}
	serveErr := make(chan error, 1)
	go func() {
		serveErr <- server.Serve(listener)
	}()
	fmt.Fprintf(diagnostics, "event=server_started listen=%s\n", authority)
	if opts.OpenBrowser {
		if opts.LaunchBrowser == nil {
			fmt.Fprintln(diagnostics, "event=browser_launch warning=launcher_unavailable")
		} else if err := opts.LaunchBrowser(ctx, origin+"/"); err != nil {
			fmt.Fprintln(diagnostics, "event=browser_launch warning=launch_failed")
		}
	}

	select {
	case err := <-serveErr:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return fmt.Errorf("serve HTTP: %w", err)
	case <-ctx.Done():
		started := time.Now()
		shutdownCtx, cancel := context.WithTimeout(context.Background(), ShutdownTimeout)
		defer cancel()
		cleanupErr := hub.drainAndWait(shutdownCtx)
		cancelOperations()
		err := server.Shutdown(shutdownCtx)
		if cleanupErr != nil {
			return fmt.Errorf("operation cleanup during shutdown: %w", cleanupErr)
		}
		if err != nil {
			_ = server.Close()
		}
		serveResult := <-serveErr
		fmt.Fprintf(diagnostics, "event=server_stopped reason=cancelled duration_ms=%d\n", time.Since(started).Milliseconds())
		if err != nil {
			return fmt.Errorf("graceful shutdown: %w", err)
		}
		if serveResult != nil && !errors.Is(serveResult, http.ErrServerClosed) {
			return fmt.Errorf("serve HTTP during shutdown: %w", serveResult)
		}
		return nil
	}
}

type lockedWriter struct {
	mu     sync.Mutex
	writer io.Writer
}

func (w *lockedWriter) Write(data []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	return w.writer.Write(data)
}

func canonicalAuthority(addr net.Addr) (string, error) {
	host, port, err := net.SplitHostPort(addr.String())
	if err != nil {
		return "", fmt.Errorf("resolve listener authority: %w", err)
	}
	ip := net.ParseIP(host)
	if ip == nil || !ip.IsLoopback() {
		return "", errors.New("listener is not a numeric loopback address")
	}
	return net.JoinHostPort(ip.String(), port), nil
}

package web

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"html/template"
	"io"
	"io/fs"
	"net/http"
	"strconv"
	"strings"
	"text/template/parse"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

//go:embed templates/*.html templates/*/*.html static/*
var assets embed.FS

var staticAssetNames = map[string]struct{}{
	"app.css": {}, "app.js": {}, "resource-monitor.css": {}, "resource-monitor.js": {},
	"run-timeline.css": {}, "run-timeline.js": {},
	"css/tokens.css": {}, "css/base.css": {}, "css/primitives.css": {}, "css/components.css": {}, "css/layouts.css": {}, "css/utilities.css": {},
	"js/app.js": {}, "js/operations.js": {}, "js/sse.js": {}, "js/study.js": {},
}

type HandlerOptions struct {
	Queries     app.WebQueries
	Operations  app.WebOperations
	Runs        app.RunUseCases
	Authority   string
	Diagnostics io.Writer
	Now         func() time.Time
	RequestID   func() string
	RootContext context.Context
	Hub         *operationHub
}

type handler struct {
	queries      app.WebQueries
	templates    *template.Template
	now          func() time.Time
	hub          *operationHub
	preparations *preparationStore
	diagnostics  io.Writer
	runs         app.RunUseCases
	qa           app.QAQueries
}

func NewHandler(opts HandlerOptions) (http.Handler, error) {
	if opts.Queries == nil {
		return nil, errors.New("web queries are required")
	}
	templates, err := parseTemplateTree(assets)
	if err != nil {
		return nil, err
	}
	if opts.Now == nil {
		opts.Now = time.Now
	}
	if opts.Diagnostics == nil {
		opts.Diagnostics = io.Discard
	}
	hub := opts.Hub
	if hub == nil {
		hub = newOperationHub(opts.RootContext, opts.Operations, opts.Now, opts.RequestID)
	}
	qa, _ := opts.Operations.(app.QAQueries)
	if qa == nil {
		qa, _ = opts.Queries.(app.QAQueries)
	}
	h := &handler{queries: opts.Queries, templates: templates, now: opts.Now, hub: hub, preparations: newPreparationStore(opts.Now, opts.RequestID), diagnostics: opts.Diagnostics, runs: opts.Runs, qa: qa}
	security := newSecurityMiddleware(opts.Authority, opts.Diagnostics, opts.Now, opts.RequestID)
	return security.wrap(h), nil
}

func parseTemplateTree(source fs.FS) (*template.Template, error) {
	if err := rejectDuplicateTemplateDefinitions(source); err != nil {
		return nil, err
	}
	templates, err := template.ParseFS(source, "templates/*.html", "templates/*/*.html")
	if err != nil {
		return nil, err
	}
	if err := validateTemplateHierarchy(templates); err != nil {
		return nil, err
	}
	return templates, nil
}

func rejectDuplicateTemplateDefinitions(source fs.FS) error {
	seen := make(map[string]string)
	var paths []string
	for _, pattern := range []string{"templates/*.html", "templates/*/*.html"} {
		matches, err := fs.Glob(source, pattern)
		if err != nil {
			return err
		}
		paths = append(paths, matches...)
	}
	for _, path := range paths {
		data, err := fs.ReadFile(source, path)
		if err != nil {
			return err
		}
		parsed, err := template.New(path).Parse(string(data))
		if err != nil {
			return fmt.Errorf("parse template %s: %w", path, err)
		}
		for _, item := range parsed.Templates() {
			name := item.Name()
			if !strings.Contains(name, "/") {
				continue
			}
			if previous := seen[name]; previous != "" {
				return fmt.Errorf("template %q is defined in both %s and %s", name, previous, path)
			}
			seen[name] = path
		}
	}
	return nil
}

func validateTemplateHierarchy(templates *template.Template) error {
	layers := map[string]int{"primitive": 0, "component": 1, "layout": 2, "page": 3}
	required := []string{
		"primitive/empty", "component/artifacts", "component/findings", "component/operation-console",
		"layout/top", "layout/bottom", "page/dashboard", "page/projects", "page/project", "page/sprint",
		"page/studies", "page/study", "page/artifact", "page/operation-confirm", "page/operation", "page/error",
	}
	for _, name := range required {
		if templates.Lookup(name) == nil {
			return fmt.Errorf("required template %q is missing", name)
		}
	}
	graph := make(map[string][]string)
	for _, item := range templates.Templates() {
		name := item.Name()
		parts := strings.SplitN(name, "/", 2)
		if len(parts) != 2 {
			continue // ParseFS also exposes empty filename roots.
		}
		level, ok := layers[parts[0]]
		if !ok {
			return fmt.Errorf("template %q has an unsupported namespace", name)
		}
		dependencies := templateDependencies(item.Tree.Root)
		for _, dependency := range dependencies {
			dependencyParts := strings.SplitN(dependency, "/", 2)
			dependencyLevel, ok := layers[dependencyParts[0]]
			if len(dependencyParts) != 2 || !ok {
				return fmt.Errorf("template %q depends on unnamespaced template %q", name, dependency)
			}
			if dependencyLevel >= level {
				return fmt.Errorf("template %q has upward or same-layer dependency %q", name, dependency)
			}
		}
		graph[name] = dependencies
	}
	visiting, visited := make(map[string]bool), make(map[string]bool)
	var visit func(string) error
	visit = func(name string) error {
		if visiting[name] {
			return fmt.Errorf("template dependency cycle includes %q", name)
		}
		if visited[name] {
			return nil
		}
		visiting[name] = true
		for _, dependency := range graph[name] {
			if err := visit(dependency); err != nil {
				return err
			}
		}
		delete(visiting, name)
		visited[name] = true
		return nil
	}
	for name := range graph {
		if err := visit(name); err != nil {
			return err
		}
	}
	return nil
}

func templateDependencies(node parse.Node) []string {
	var dependencies []string
	var walk func(parse.Node)
	walk = func(current parse.Node) {
		switch value := current.(type) {
		case *parse.ListNode:
			if value != nil {
				for _, child := range value.Nodes {
					walk(child)
				}
			}
		case *parse.TemplateNode:
			dependencies = append(dependencies, value.Name)
		case *parse.IfNode:
			walk(value.List)
			walk(value.ElseList)
		case *parse.RangeNode:
			walk(value.List)
			walk(value.ElseList)
		case *parse.WithNode:
			walk(value.List)
			walk(value.ElseList)
		}
	}
	walk(node)
	return dependencies
}

type routeMatch struct {
	name   string
	params []string
	known  bool
	api    bool
	static bool
}

func (h *handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	match := matchRoute(r.URL.Path)
	if !match.known {
		if match.api {
			h.writeError(w, r, http.StatusNotFound, "not_found", "The requested resource was not found.")
		} else {
			h.renderError(w, r, http.StatusNotFound, "Page not found", "The requested page was not found.")
		}
		return
	}
	allowed := allowedMethods(match)
	if !methodAllowed(r.Method, allowed) {
		w.Header().Set("Allow", strings.Join(allowed, ", "))
		h.writeRouteError(w, r, match.api, http.StatusMethodNotAllowed, "method_not_allowed", "The method is not supported for this resource.")
		return
	}
	if r.Method == http.MethodHead {
		w = headResponseWriter{ResponseWriter: w}
	}
	if match.static {
		h.serveStatic(w, r, match.params[0])
		return
	}
	h.dispatch(w, r, match)
}

func allowedMethods(match routeMatch) []string {
	switch match.name {
	case "api_operation_prepare":
		return []string{http.MethodPost}
	case "api_operations":
		return []string{http.MethodGet, http.MethodHead, http.MethodPost}
	case "operation_prepare", "operation_start", "operation_cancel", "run_cancel", "sprint_create":
		return []string{http.MethodPost}
	case "api_operation":
		return []string{http.MethodGet, http.MethodDelete}
	case "api_operation_events":
		return []string{http.MethodGet}
	case "api_run":
		return []string{http.MethodGet, http.MethodHead, http.MethodDelete}
	case "api_run_events":
		return []string{http.MethodGet, http.MethodHead}
	default:
		return []string{http.MethodGet, http.MethodHead}
	}
}

func methodAllowed(method string, allowed []string) bool {
	for _, candidate := range allowed {
		if method == candidate {
			return true
		}
	}
	return false
}

